//! The user guide's settings reference (PLAN.md Phase 7c, D1),
//! `docs/user-guide/settings-reference.md`: every setting the app keeps,
//! under its section of Settings, named as the UI names it (from
//! `en.json`) with its default (from the Rust defaults) and its range.
//!
//! Generated by a test and checked by it, like the TypeScript bindings:
//! the test fails while the committed file differs, and
//! `ANOMP_WRITE_BINDINGS=1 cargo test bindings` rewrites it. It also fails
//! when a setting has no row here (every value in the defaults must be
//! covered, or listed in `UNLISTED` with why) or a row names a setting or
//! a message that's gone, so a new setting can't be left out of the guide.

use std::collections::BTreeMap;
use std::fmt::Write as _;
use std::path::{Path, PathBuf};

use serde_json::Value;

use crate::anomp::EffectUnit;
use crate::library::rules::SortSettings;
use crate::metadata::settings::{ServiceSettings, SourceId};
use crate::settings::AppSettings;

/// The UI's messages, by key.
struct Labels(BTreeMap<String, Value>);

impl Labels {
    fn load() -> Labels {
        let path = Path::new(env!("CARGO_MANIFEST_DIR")).join("../src/lib/i18n/en.json");
        let text = std::fs::read_to_string(&path).expect("en.json is readable");
        Labels(serde_json::from_str(&text).expect("en.json is a JSON object"))
    }

    /// The message `key`, its plural's "other" form if it has one.
    fn get(&self, key: &str) -> String {
        match self.0.get(key) {
            Some(Value::String(text)) => text.clone(),
            Some(Value::Object(forms)) => forms["other"].as_str().unwrap_or_default().to_owned(),
            _ => panic!("en.json has no message {key}"),
        }
    }

    /// The message `key` with `{name}` placeholders filled in.
    fn fill(&self, key: &str, values: &[(&str, &str)]) -> String {
        values.iter().fold(self.get(key), |text, (name, value)| {
            text.replace(&format!("{{{name}}}"), value)
        })
    }
}

/// How a value is shown.
enum Shown {
    /// On or off.
    Switch,
    /// One of several, each a JSON string with its label's key.
    Choice(&'static [(&'static str, &'static str)]),
    /// A number with its unit ("dB", "s"…, or "" for none).
    Number(&'static str),
    /// Anything else, written by a function.
    Custom(fn(&Value, &Labels) -> String),
}

/// One row of the reference: a setting, or a group of them shown as one.
struct Row {
    /// Its section of Settings (the `settings.<id>` message).
    section: &'static str,
    /// Where it is in the settings' JSON; it covers everything under it.
    path: &'static str,
    /// The UI's name for it.
    label: &'static str,
    shown: Shown,
    /// The values it can take, when that isn't plain from the choices.
    range: &'static str,
}

const fn row(
    section: &'static str,
    path: &'static str,
    label: &'static str,
    shown: Shown,
    range: &'static str,
) -> Row {
    Row {
        section,
        path,
        label,
        shown,
        range,
    }
}

