fn list(value: &Value, choices: &[(&str, &str)], labels: &Labels, empty: &str) -> String {
    let names: Vec<String> = value
        .as_array()
        .into_iter()
        .flatten()
        .map(|item| choice(item, choices, labels))
        .collect();
    if names.is_empty() {
        labels.get(empty)
    } else {
        names.join(", ")
    }
}

fn choice(value: &Value, choices: &[(&str, &str)], labels: &Labels) -> String {
    let id = value.as_str().unwrap_or_default();
    let (_, key) = choices
        .iter()
        .find(|(candidate, _)| *candidate == id)
        .unwrap_or_else(|| panic!("no label for the choice {id}"));
    labels.get(key)
}

fn number(value: &Value) -> String {
    let number = value.as_f64().unwrap_or_default();
    if number.fract() == 0.0 {
        format!("{number:.0}")
    } else {
        format!("{number}")
    }
}

fn signed_db(value: &Value) -> String {
    let db = value.as_f64().unwrap_or_default();
    if db > 0.0 {
        format!("+{} dB", number(value))
    } else {
        format!("{} dB", number(value))
    }
}

