/// An equaliser profile: its preset's name, or the bands' gains.
fn profile(value: &Value, labels: &Labels) -> String {
    let preset = value["preset"].as_str().unwrap_or("custom");
    labels.get(&format!("eq.preset.{preset}"))
}

