/// The sources for one kind of data, in the order they're tried.
fn order(value: &Value, _: &Labels) -> String {
    value
        .as_array()
        .into_iter()
        .flatten()
        .filter_map(|id| SourceId::from_str(id.as_str()?))
        .map(|id| id.info().name)
        .collect::<Vec<_>>()
        .join(", then ")
}

/// Every setting's default, as one JSON value: `app` (`AppSettings`),
/// `sort` and `services`.
fn defaults() -> Value {
    serde_json::json!({
        "app": AppSettings::default(),
        "sort": SortSettings::default(),
        "services": ServiceSettings::default(),
    })
}

/// Every value's path in `value` (an array is one value).
fn leaves(value: &Value, path: String, out: &mut Vec<String>) {
    match value {
        Value::Object(fields) if !fields.is_empty() => {
            for (name, field) in fields {
                leaves(field, format!("{path}.{name}"), out);
            }
        }
        _ => out.push(path),
    }
}

fn at<'a>(value: &'a Value, path: &str) -> Option<&'a Value> {
    path.split('.')
        .try_fold(value, |value, name| value.as_object()?.get(name))
}

fn covers(row: &str, leaf: &str) -> bool {
    leaf == row || leaf.starts_with(&format!("{row}."))
}

fn effect_rows(defaults: &Value, labels: &Labels) -> Vec<(String, String, String)> {
    let mut rows = Vec::new();
    let mut catalog = crate::effects::catalog().to_vec();
    catalog.sort_by_key(|info| info.position);
    for info in catalog {
        let effect = &defaults["app"]["effects"][&info.id];
        let name = labels.get(&format!("effects.{}", info.id));
        let state = if effect["enabled"] == Value::Bool(true) {
            "On"
        } else {
            "Off"
        };
        rows.push((
            name.clone(),
            format!(
                "{state}, {} {}",
                labels.get("effects.mix"),
                percent(info.default_mix)
            ),
            "on or off; mix 0% to 100%".to_owned(),
        ));
        for param in &info.params {
            let shown = |value: f64| effect_value(value, param.unit, labels);
            rows.push((
                format!(
                    "{name} › {}",
                    labels.get(&format!("effects.param.{}", param.id))
                ),
                shown(
                    effect["params"][&param.id]
                        .as_f64()
                        .unwrap_or(param.default_value),
                ),
                format!("{} to {}", shown(param.min), shown(param.max)),
            ));
        }
    }
    rows
}

fn percent(ratio: f64) -> String {
    format!("{:.0}%", ratio * 100.0)
}

/// A parameter's value as the Effects section shows it.
fn effect_value(value: f64, unit: EffectUnit, labels: &Labels) -> String {
    let short = |number: f64| {
        let rounded = (number * 100.0).round() / 100.0;
        if rounded.fract() == 0.0 {
            format!("{rounded:.0}")
        } else {
            format!("{rounded}")
        }
    };
    let (key, number) = match unit {
        EffectUnit::Ratio => return percent(value).replace('-', "−"),
        EffectUnit::Hertz if value >= 1000.0 => (
            "effects.unit.kilohertz",
            short((value / 100.0).round() / 10.0),
        ),
        EffectUnit::Hertz => ("effects.unit.hertz", short(value)),
        EffectUnit::Milliseconds => ("effects.unit.milliseconds", short(value)),
        EffectUnit::Seconds => ("effects.unit.seconds", short(value)),
        EffectUnit::Bits => ("effects.unit.bits", short(value)),
    };
    labels.fill(key, &[("value", &number)])
}

fn shown(row: &Row, value: &Value, labels: &Labels) -> String {
    match &row.shown {
        Shown::Switch => match value {
            Value::Bool(true) => "On".to_owned(),
            Value::Bool(false) => "Off".to_owned(),
            _ => panic!("{} isn't a switch", row.path),
        },
        Shown::Choice(choices) => choice(value, choices, labels),
        Shown::Number("") => number(value),
        Shown::Number(unit) => format!("{} {unit}", number(value)),
        Shown::Custom(write) => write(value, labels),
    }
}

/// The range column for a row: its own, or its choices'.
fn range(row: &Row, labels: &Labels) -> String {
    match &row.shown {
        Shown::Switch => "On or off".to_owned(),
        Shown::Choice(choices) => choices
            .iter()
            .map(|(_, key)| labels.get(key))
            .collect::<Vec<_>>()
            .join(", "),
        _ => row.range.to_owned(),
    }
}

/// A table cell: no line breaks or bars.
fn cell(text: &str) -> String {
    text.replace('|', "\\|").replace('\n', " ")
}

fn generate() -> String {
    let labels = Labels::load();
    let defaults = defaults();
    let rows: Vec<&Row> = APP_ROWS.iter().chain(OTHER_ROWS).collect();

    // Every row names a setting, and every setting has a row.
    for row in &rows {
        assert!(
            at(&defaults, row.path).is_some(),
            "the reference's row {} names no setting",
            row.path
        );
        assert!(
            SECTIONS.contains(&row.section),
            "{}: no section {}",
            row.path,
            row.section
        );
        assert!(!range(row, &labels).is_empty(), "{}: no range", row.path);
    }
    let mut all = Vec::new();
    leaves(&defaults, String::new(), &mut all);
    for leaf in all.iter().map(|leaf| &leaf[1..]) {
        let listed = rows.iter().any(|row| covers(row.path, leaf))
            || leaf.starts_with("app.effects.")
            || UNLISTED.iter().any(|(path, _)| covers(path, leaf));
        assert!(
            listed,
            "the setting {leaf} isn't in the user guide's settings reference: add a row to guide.rs"
        );
    }
    for id in VISUALIZATIONS {
        labels.get(&format!("viz.{id}.name"));
    }

    let mut out = String::from(
        "<!-- Generated by `cargo test` from the app's settings (app/src-tauri/src/guide.rs);\n     \
         don't edit. After changing a setting or its label, run\n     \
         `ANOMP_WRITE_BINDINGS=1 cargo test bindings` in app/src-tauri. -->\n\n\
         # Settings reference\n\n\
         Every setting ano-mp keeps, under the section of Settings it is in, with the\n\
         value it has until you change it. [Chapter 11](11-settings.md) explains what\n\
         each one does. To open Settings, choose **ano-mp › Settings…** (⌘,).\n\n\
         Each section's **Reset to defaults** button (or **Reset**) puts that\n\
         section's settings back to the values below.\n",
    );
    for section in SECTIONS {
        let _ = write!(out, "\n## {}\n\n", labels.get(section));
        out.push_str("| Setting | Starts as | Can be |\n|---|---|---|\n");
        if *section == "settings.effects" {
            for row in rows.iter().filter(|row| row.section == *section) {
                let value = at(&defaults, row.path).unwrap();
                let _ = writeln!(
                    out,
                    "| {} | {} | {} |",
                    cell(&labels.get(row.label)),
                    cell(&shown(row, value, &labels)),
                    cell(&range(row, &labels))
                );
            }
            for (name, value, range) in effect_rows(&defaults, &labels) {
                let _ = writeln!(
                    out,
                    "| {} | {} | {} |",
                    cell(&name),
                    cell(&value),
                    cell(&range)
                );
            }
            continue;
        }
        for row in rows.iter().filter(|row| row.section == *section) {
            let value = at(&defaults, row.path).unwrap();
            let _ = writeln!(
                out,
                "| {} | {} | {} |",
                cell(&labels.get(row.label)),
                cell(&shown(row, value, &labels)),
                cell(&range(row, &labels))
            );
        }
    }
    out.push_str(
        "\nThe online sources' keys (a Discogs token, a ListenBrainz token) aren't settings:\n\
         they are kept in the macOS keychain, and none is saved at first. The folders in your\n\
         library and the recordings' folder are kept apart from the settings too.\n",
    );
    out
}

fn reference_path() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../../docs/user-guide/settings-reference.md")
}

#[test]
fn bindings_user_guide_settings_reference_is_up_to_date() {
    let path = reference_path();
    let generated = generate();
    if std::env::var_os("ANOMP_WRITE_BINDINGS").is_some() {
        std::fs::create_dir_all(path.parent().unwrap()).unwrap();
        std::fs::write(&path, &generated).unwrap();
        return;
    }
    let committed = std::fs::read_to_string(&path).unwrap_or_default();
    assert!(
        committed == generated,
        "{} is out of date: run `ANOMP_WRITE_BINDINGS=1 cargo test bindings` in src-tauri",
        path.display()
    );
}
